const BASE='https://api.discogs.com',SIX_HOURS=21600;let nextUpstream=0,activeCollection=BOOTSTRAP;
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}})}
async function upstream(path){const now=Date.now(),delay=Math.max(0,nextUpstream-now);nextUpstream=Math.max(now,nextUpstream)+2600;if(delay>20000)throw Error('Several records are loading. Please try again shortly.');if(delay)await new Promise(r=>setTimeout(r,delay));const r=await fetch(BASE+path,{headers:{'User-Agent':'MusicThatTravelsPrototype/0.2 (personal collection visualisation)','Accept':'application/json'}});if(!r.ok){if(r.status===429)throw Error('Discogs rate limit reached. Please wait a minute and retry.');throw Error('Discogs returned '+r.status)}return r.json()}
function slim(row){const b=row.basic_information;return {instance_id:row.instance_id,id:b.id,master_id:b.master_id||0,title:b.title,year:b.year||0,thumb:b.thumb||'',cover:b.cover_image||'',artists:[...new Map((b.artists||[]).map(a=>[a.id,{id:a.id,name:a.name}])).values()],labels:(b.labels||[]).map(l=>({id:l.id,name:l.name,catno:l.catno||''})),styles:b.styles||[],genres:b.genres||[],formats:b.formats||[]}}
function release(d){return {id:d.id,country:d.country||null,released:d.released||null,year:d.year||null,credits:(d.extraartists||[]).map(c=>({name:c.name,role:c.role||''})),recorded_at:(d.companies||[]).filter(c=>c.entity_type_name==='Recorded At').map(c=>c.name),fetched_at:new Date().toISOString()}}
function master(d){return {id:d.id,year:d.year||null,title:d.title||'',fetched_at:new Date().toISOString()}}
function fresh(v){return v&&Date.now()-Date.parse(v.fetched_at)<SIX_HOURS*1000}
function getCache(){try{return typeof caches!=='undefined'?caches.default:null}catch{return null}}
async function readCache(key){try{const cache=getCache();return cache?await cache.match(key):null}catch{return null}}
async function writeCache(key,response,ctx){const task=(async()=>{try{const cache=getCache();if(cache)await cache.put(key,response)}catch{}})();if(ctx&&typeof ctx.waitUntil==='function')ctx.waitUntil(task);else await task}
async function cached(request,ctx,load){const key=new Request(new URL(request.url).origin+new URL(request.url).pathname);const found=await readCache(key);if(found){try{const d=await found.json();if(fresh(d)){if(d.entries)activeCollection=d;return json(d)}}catch{}}const result=await load();const ttl=Math.max(1,Math.min(SIX_HOURS,Math.floor((Date.parse(result.fetched_at)+SIX_HOURS*1000-Date.now())/1000)));await writeCache(key,new Response(JSON.stringify(result),{headers:{'Content-Type':'application/json','Cache-Control':'public,max-age='+ttl}}),ctx);return json(result)}
export default {async fetch(request,env,ctx){const url=new URL(request.url);if(request.method!=='GET')return json({error:'Method not allowed'},405);try{if(url.pathname==='/api/geography'){const etag='\"'+GEOGRAPHY_VERSION+'\"',headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':url.searchParams.get('v')===GEOGRAPHY_VERSION?'public,max-age=31536000,immutable':'public,max-age=300',ETag:etag,'X-Content-Type-Options':'nosniff'};return new Response(request.headers.get('if-none-match')===etag?null:GEOGRAPHY_DATA_JSON,{status:request.headers.get('if-none-match')===etag?304:200,headers});}if(url.pathname==='/api/collection')return await cached(request,ctx,async()=>{if(fresh(BOOTSTRAP)){activeCollection=BOOTSTRAP;return BOOTSTRAP;}let entries=[],page=1,total=0;do{const d=await upstream('/users/chris_py/collection/folders/0/releases?per_page=100&page='+page);entries.push(...d.releases.map(slim));total=d.pagination.items;if(page>=d.pagination.pages)break;page++}while(page<=100);activeCollection={username:'chris_py',entries,total,release_details:BOOTSTRAP.release_details,master_details:BOOTSTRAP.master_details,fetched_at:new Date().toISOString()};return activeCollection});if(url.pathname==='/api/countries')return json(COUNTRIES);if(url.pathname==='/api/musical-origins')return json(ORIGIN_PILOT);if(url.pathname==='/api/artwork-analysis')return json(ARTWORK);if(url.pathname==='/api/atlas')return json({...BOOTSTRAP,music_locations:MUSIC_LOCATIONS,audit:AUDIT});if(url.pathname==='/api/dataset-audit')return json(AUDIT);if(url.pathname==='/api/land')return json(LAND);if(url.pathname==='/api/music-locations')return json(MUSIC_LOCATIONS);if(url.pathname==='/api/experiment')return json(TEST_SET);const artMatch=url.pathname.match(/^\/api\/experiment-cover\/(\d+)$/);if(artMatch){const rid=Number(artMatch[1]);if(!TEST_SET.ids.includes(rid))return new Response(null,{status:404});const cacheKey=new Request(url.origin+'/experiments/music-that-travels'+url.pathname),found=await readCache(cacheKey);if(found)return found;const n=activeCollection.entries.find(n=>n.id===rid);if(!n?.master_id)return new Response(null,{status:404});let master=TEST_SET.masters[String(n.master_id)];if(!master){const d=await upstream('/masters/'+n.master_id),im=(d.images||[]).find(x=>x.type==='primary')||(d.images||[])[0];master={id:d.id,thumb:im?.uri150||im?.uri,fetched_at:new Date().toISOString()}}if(!master?.thumb?.startsWith('https://i.discogs.com/'))return new Response(null,{status:404});const image=await fetch(master.thumb,{headers:{'User-Agent':'MusicThatTravelsPrototype/0.4','Referer':'https://www.discogs.com/'},signal:AbortSignal.timeout(15000)});if(!image.ok)return new Response(null,{status:404});const response=new Response(image.body,{headers:{'Content-Type':image.headers.get('Content-Type')||'image/jpeg','Cache-Control':'public,max-age=21600','X-Content-Type-Options':'nosniff'}});await writeCache(cacheKey,response.clone(),ctx);return response;}const imageMatch=url.pathname.match(/^\/api\/(?:cover|artwork)\/(\d+)$/);if(imageMatch){const key=new Request(url.origin+'/experiments/music-that-travels'+url.pathname),found=await readCache(key);if(found)return found;const n=activeCollection.entries.find(n=>String(n.id)===imageMatch[1]);const imageURL=url.pathname.startsWith('/api/artwork/')?(n?.cover||n?.thumb):n?.thumb;if(!n||!imageURL?.startsWith('https://i.discogs.com/'))return new Response(null,{status:404});const image=await fetch(imageURL,{headers:{'User-Agent':'MusicThatTravelsPrototype/0.2','Referer':'https://www.discogs.com/'},signal:AbortSignal.timeout(15000)});if(!image.ok)return new Response(null,{status:404});const response=new Response(image.body,{headers:{'Content-Type':image.headers.get('Content-Type')||'image/jpeg','Cache-Control':'public,max-age=21600','X-Content-Type-Options':'nosniff'}});await writeCache(key,response.clone(),ctx);return response;}const match=url.pathname.match(/^\/api\/(release|master)\/(\d+)$/);if(match)return await cached(request,ctx,async()=>{const type=match[1],id=match[2],boot=BOOTSTRAP[type==='release'?'release_details':'master_details']?.[id];if(boot)return boot;const d=await upstream('/'+(type==='release'?'releases':'masters')+'/'+id);return type==='release'?release(d):master(d)});if(url.pathname==='/favicon.ico')return new Response(null,{status:204});if(['/','/index.html','/geography','/chromatic','/dataset'].includes(url.pathname))return new Response(url.pathname==='/dataset'?COVERAGE:url.pathname==='/geography'?GEOGRAPHY:url.pathname==='/chromatic'?HTML:HUB,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}});return json({error:'Not found'},404)}catch(e){return json({error:e.message||'Discogs is temporarily unavailable'},502)}}};
